CREATE OR REPLACE FUNCTION privacy_private.linked_delete_lock_graph_v1(p_owner uuid, p_trip uuid, s jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform pg_advisory_xact_lock(hashtextextended(p_owner::text,34));
 perform 1 from auth.users where id=p_owner for key share nowait;if not found then raise exception 'FORBIDDEN';end if;
 perform 1 from identity_private.mobile_accounts where owner_id=p_owner for update;
 perform 1 from turn_private.service_tasks where id=any(privacy_private.linked_delete_array_v1(s->'taskIds')) order by id for update nowait;
 perform 1 from public.trips where id=p_trip and owner_id=p_owner for update nowait;if not found then raise exception 'FORBIDDEN';end if;
 perform 1 from public.chat_threads where id=any(privacy_private.linked_delete_array_v1(s->'threadIds')) order by id for update nowait;
 perform 1 from public.turns where id=any(privacy_private.linked_delete_array_v1(s->'turnIds')) order by id for update nowait;
 perform 1 from turn_private.assistant_goals where id=any(privacy_private.linked_delete_array_v1(s->'goalIds')) order by id for update nowait;
 perform 1 from turn_private.assistant_messages where id=any(privacy_private.linked_delete_array_v1(s->'messageIds')) order by id for update nowait;
 perform 1 from turn_private.result_artifacts where id=any(privacy_private.linked_delete_array_v1(s->'artifactIds')) order by id for update nowait;
